import React, { useEffect, useMemo, useState } from 'react';
import {
  ABILITY_KEYS,
  APP_VERSION,
  COALITION_LABELS,
  IDEOLOGY_DIMENSIONS,
  PARTIES,
  POPULATION_GROUP_ERA_LABELS,
  RARITIES,
  SCHEMA_VERSION
} from './constants.js';
import { createWorld, currentEra, getDistrict, getPolitician, getState, getStateFavorability, getStateRecognition } from './world.js';
import {
  advanceToEndOfYear,
  advanceToNextEvent,
  advanceWeeks,
  getCycleLabel,
  moveToNextYear,
  simulateYears
} from './simulation.js';
import { deleteWorld, getSaveMetadata, loadWorld, saveWorld } from './storage.js';

const NAV_ITEMS = [
  ['home', 'Front Page'], ['magazine', 'Chronicle'], ['elections', 'Elections'], ['politicians', 'Politicians'],
  ['parties', 'Parties'], ['congress', 'Congress'], ['states', 'States'], ['government', 'Government'],
  ['world', 'World'], ['history', 'History'], ['rankings', 'Rankings'], ['saves', 'Saves']
];

const initialSeed = 1776 + new Date().getDate() * 97;
const initialWorld = createWorld(initialSeed);

function party(id, world = window.__pcWorld) { return world?.parties?.[id] || PARTIES[id] || PARTIES.union; }
function partyShortName(name, fallback='—') { return name ? name.split(/\s+/).map((x)=>x[0]).join('').slice(0,3).toUpperCase() : fallback; }
function fmt(value, digits = 0) { return Number(value ?? 0).toLocaleString(undefined, { maximumFractionDigits: digits, minimumFractionDigits: digits }); }
function pct(value) { return `${fmt(value, 1)}%`; }
function officeLabel(p) {
  if (!p) return 'Unknown';
  const state = getState(window.__pcWorld || {}, p.officeStateId);
  return p.office === 'Representative' ? `Representative · ${getDistrict(window.__pcWorld || {}, p.officeDistrictId)?.name || ''}` : p.office === 'Governor' || p.office === 'Senator' ? `${p.office} · ${state?.name || ''}` : p.office;
}

function Card({ title, eyebrow, children, className = '' }) {
  return <section className={`card ${className}`}>{(title || eyebrow) && <header className="card-head">{eyebrow && <span>{eyebrow}</span>}{title && <h2>{title}</h2>}</header>}{children}</section>;
}

function PageHeader({ eyebrow, title, description, actions }) {
  return <div className="page-header"><div><span>{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{actions && <div className="page-actions">{actions}</div>}</div>;
}

function Metric({ label, value, detail }) {
  return <div className="metric"><span>{label}</span><strong>{value}</strong>{detail && <small>{detail}</small>}</div>;
}

function Avatar({ politician, size = 'md' }) {
  if (!politician) return <span className={`avatar ${size}`}>?</span>;
  return <span className={`avatar ${size}`} style={{ '--rarity': RARITIES[politician.rarity]?.color, '--party': party(politician.partyId).color }}>{politician.initials}</span>;
}

function Rarity({ rarity }) { return <span className="rarity" style={{ '--rarity': RARITIES[rarity]?.color }}>{rarity}</span>; }

function PoliticianButton({ world, id, onOpen, compact = false }) {
  const p = getPolitician(world, id);
  if (!p) return <span>Unknown</span>;
  return <button className={`person-link ${compact ? 'compact' : ''}`} onClick={() => onOpen(p.id)}><Avatar politician={p} size={compact ? 'xs' : 'sm'} /><span><strong>{p.name}</strong><small>{p.office} · {p.rarity}</small></span></button>;
}

function SplitBar({ union, liberty, total }) {
  const u = total ? union / total * 100 : 50;
  return <div className="split-wrap"><div className="split-label"><b style={{ color: party('union').color }}>{party('union').short} {union}</b><span>{total}</span><b style={{ color: party('liberty').color }}>{liberty} {party('liberty').short}</b></div><div className="split-bar"><span style={{ width: `${u}%`, background: party('union').color }} /><span style={{ width: `${100-u}%`, background: party('liberty').color }} /></div></div>;
}

function Meter({ value, partyId = null }) {
  return <div className="meter"><span style={{ width: `${clampValue(value)}%`, background: partyId ? party(partyId).color : undefined }} /></div>;
}
function clampValue(v) { return Math.max(0, Math.min(100, Number(v) || 0)); }

function Sparkline({ values }) {
  if (!values?.length) return <span className="empty">No history yet</span>;
  const width = 240; const height = 58;
  const min = Math.min(...values); const max = Math.max(...values); const range = max-min || 1;
  const points = values.map((value, index) => `${values.length === 1 ? width/2 : index/(values.length-1)*width},${height-6-(value-min)/range*(height-12)}`).join(' ');
  return <svg className="spark" viewBox={`0 0 ${width} ${height}`} role="img"><polyline points={points} fill="none" stroke="currentColor" strokeWidth="3" /></svg>;
}

function SimControls({ world, disabled, onAdvance, onNextEvent, onEndYear, onReview }) {
  return <div className="sim-controls"><div><span>YEAR {world.date.year}</span><strong>WEEK {world.date.week}</strong><em>{getCycleLabel(world)}</em></div><div className="sim-buttons">{world.annualReview ? <button className="primary" onClick={onReview}>Open annual review</button> : <><button disabled={disabled} onClick={() => onAdvance(1)}>+1 week</button><button disabled={disabled} onClick={() => onAdvance(4)}>+4 weeks</button><button disabled={disabled} onClick={onNextEvent}>Next major event</button><button disabled={disabled} onClick={onEndYear}>End of year</button></>}</div></div>;
}

function StoryCard({ world, story, onOpenPolitician, onOpenState, lead = false }) {
  const subject = getPolitician(world, story.subjectId);
  const state = getState(world, story.stateId);
  return <article className={`story ${lead ? 'lead' : ''}`}><div className="story-meta"><span>{story.category}</span><b>Y{story.year} · W{story.week}</b></div><h3>{story.title}</h3><p>{story.text}</p><div className="story-links">{subject && <button onClick={() => onOpenPolitician(subject.id)}>{subject.name} →</button>}{state && state.id !== 'capital-district' && <button onClick={() => onOpenState(state.id)}>{state.name} →</button>}</div></article>;
}

function HomePage({ world, openPolitician, openState, setPage }) {
  const president = getPolitician(world, world.government.presidentId);
  const governors = world.states.map((s) => getPolitician(world, s.governorId)).filter(Boolean);
  const rising = [...world.politicians].filter((p) => p.status === 'Active' && p.age <= 42 && p.office !== 'President').sort((a,b) => (b.momentum+b.stateRecognition*0.35+b.nationalRecognition*0.5+RARITIES[b.rarity].weight*2)-(a.momentum+a.stateRecognition*0.35+a.nationalRecognition*0.5+RARITIES[a.rarity].weight*2)).slice(0,8);
  const topGovernors = governors.sort((a,b) => (b.governingRecord.stateRankChange+b.approval*0.25+b.nationalRecognition*0.3)-(a.governingRecord.stateRankChange+a.approval*0.25+a.nationalRecognition*0.3)).slice(0,6);
  const latest = world.magazine.slice(0,7);
  return <div className="page">
    <PageHeader eyebrow={`${world.country.name} · Living political history`} title="A Republic Writing Its Own History" description={`${world.politicians.filter((p) => p.status === 'Active').length.toLocaleString()} political careers unfold in the ${currentEra(world).name}. Parties, institutions, social questions, wars, and national development can diverge from historical expectations.`} />
    <div className="hero-grid">
      <Card className="president-card" eyebrow="THE ADMINISTRATION" title={president.name}>
        <div className="president-main"><Avatar politician={president} size="xl" /><div><Rarity rarity={president.rarity} /><p>{party(president.partyId).name} · President since Year {president.officeSince}</p><button onClick={() => openPolitician(president.id)}>Open complete presidential record →</button></div></div>
        <div className="metric-grid"><Metric label="Approval" value={pct(president.approval)} /><Metric label="National popularity" value={pct(president.nationalPopularity)} /><Metric label="Legacy" value={fmt(president.legacy,1)} /><Metric label="Policies" value={president.policyRecord.length} /></div>
      </Card>
      <Card eyebrow="NATIONAL BALANCE" title="Power at a glance"><SplitBar union={world.government.house.union} liberty={world.government.house.liberty} total={435} /><SplitBar union={world.government.senate.union} liberty={world.government.senate.liberty} total={100} /><div className="metric-grid compact"><Metric label="Growth" value={`${fmt(world.economy.growth,1)}%`} /><Metric label="Unemployment" value={`${fmt(world.economy.unemployment,1)}%`} /><Metric label="Inflation" value={`${fmt(world.economy.inflation,1)}%`} /><Metric label="Confidence" value={fmt(world.economy.confidence,1)} /></div></Card>
    </div>
    <Card eyebrow="THE LONG ARC" title={`${currentEra(world).name} · ${currentEra(world).technology}`}><div className="metric-grid large"><Metric label="Population" value={`${fmt(world.country.population,1)}m`} /><Metric label="GDP / capita" value={fmt(world.country.nationalStats.gdpPerCapita,1)} /><Metric label="Quality of life" value={fmt(world.country.society.qualityLife,1)} /><Metric label="Literacy" value={`${fmt(world.country.society.literacy,1)}%`} /><Metric label="Military strength" value={fmt(world.country.nationalStats.military,1)} /><Metric label="Civil rights" value={fmt(world.country.society.civilRights,1)} /></div><p className="long-copy">Current historical pressures: {currentEra(world).pressures.join(' · ')}. Slavery: {world.country.society.slaveryLegal?`legal (${fmt(world.country.society.slaveryShare,1)}% of population)`:'abolished'} · Indigenous integration {fmt(world.country.society.indigenousIntegration,1)} · Tax burden {fmt(world.country.society.taxBurden,1)}%.</p></Card>
    <div className="content-grid two-one">
      <Card eyebrow="THE LATEST ISSUE" title={latest[0]?.title || 'The Chronicle'}>{latest.length ? <><StoryCard world={world} story={latest[0]} onOpenPolitician={openPolitician} onOpenState={openState} lead /><div className="story-list">{latest.slice(1,5).map((story) => <StoryCard key={story.id} world={world} story={story} onOpenPolitician={openPolitician} onOpenState={openState} />)}</div><button className="text-button" onClick={() => setPage('magazine')}>Read the complete Chronicle →</button></> : <p>No stories yet.</p>}</Card>
      <Card eyebrow="CAREERS TO WATCH" title="The next generation"><div className="ranking-list">{rising.map((p,index) => <button key={p.id} onClick={() => openPolitician(p.id)}><span>{index+1}</span><Avatar politician={p} size="xs" /><div><strong>{p.name}</strong><small>Age {p.age} · {p.office} · state recognition {fmt(p.stateRecognition,1)}</small></div><Rarity rarity={p.rarity} /></button>)}</div></Card>
    </div>
    <Card eyebrow="EXECUTIVE RECORDS" title="Governors building national cases"><div className="person-grid">{topGovernors.map((p) => { const state=getState(world,p.officeStateId); return <button key={p.id} className="person-tile" onClick={() => openPolitician(p.id)}><Avatar politician={p} /><div><strong>{p.name}</strong><span>{state.name} · Year {world.date.year-p.officeSince+1} in office</span><small>Approval {pct(p.approval)} · economic rank change {p.governingRecord.stateRankChange>=0?'+':''}{fmt(p.governingRecord.stateRankChange,1)}</small></div></button>;})}</div></Card>
  </div>;
}

function MagazinePage({ world, openPolitician, openState }) {
  const [category,setCategory]=useState('All');
  const categories=['All',...new Set(world.magazine.map((story)=>story.category))];
  const stories=world.magazine.filter((story)=>category==='All'||story.category===category);
  return <div className="page"><PageHeader eyebrow={`Year ${world.date.year}, Week ${world.date.week}`} title="The National Chronicle" description="Campaigns, state transformations, policy consequences, scandals, rivalries, and the careers that may define an era." actions={<select value={category} onChange={(e)=>setCategory(e.target.value)}>{categories.map((c)=><option key={c}>{c}</option>)}</select>} /><div className="magazine-grid">{stories.slice(0,80).map((story,index)=><StoryCard key={story.id} world={world} story={story} onOpenPolitician={openPolitician} onOpenState={openState} lead={index===0} />)}</div></div>;
}

function ElectionResultTable({ world, records, openPolitician }) {
  return <div className="table-wrap"><table><thead><tr><th>Year</th><th>Office</th><th>Race</th><th>First party</th><th>Second party</th><th>Winner</th><th>Margin</th></tr></thead><tbody>{records.map((r)=><tr key={r.id}><td>Y{r.year}</td><td>{r.office}</td><td>{r.districtId?getDistrict(world,r.districtId)?.name:getState(world,r.stateId)?.name}</td><td><small>{partyShortName(r.unionPartyName,party('union').short)}</small> {pct(r.unionShare)}</td><td><small>{partyShortName(r.libertyPartyName,party('liberty').short)}</small> {pct(r.libertyShare)}</td><td><button onClick={()=>openPolitician(r.winnerId)}>{getPolitician(world,r.winnerId)?.name}</button></td><td>{fmt(r.margin,1)}</td></tr>)}</tbody></table></div>;
}

function ElectionsPage({ world, openPolitician, openState }) {
  const [tab,setTab]=useState('presidential');
  const latest=world.elections[0];
  const pending=world.pendingRaces;
  const latestPrimaries=world.primaryArchive.slice(0,120);
  return <div className="page"><PageHeader eyebrow="Primaries, campaigns, and election night" title="Elections" description="Every major office has named incumbents, party primaries, challengers, and permanent results." /><div className="tabs">{['presidential','federal races','primaries'].map((t)=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div>
    {tab==='presidential'&&<><Card eyebrow={world.electionCycle.phase} title={cycleElectionTitle(world)}><div className="ticket-grid"><PoliticianButton world={world} id={world.electionCycle.unionNomineeId||latest?.unionCandidateId} onOpen={openPolitician}/><div className="versus">VS</div><PoliticianButton world={world} id={world.electionCycle.libertyNomineeId||latest?.libertyCandidateId} onOpen={openPolitician}/></div>{latest&&<div className="metric-grid"><Metric label={`${partyShortName(latest.unionPartyName,party('union').short)} EV`} value={latest.unionEV}/><Metric label={`${partyShortName(latest.libertyPartyName,party('liberty').short)} EV`} value={latest.libertyEV}/><Metric label="Turnout" value={fmt(latest.turnout)}/><Metric label="Winner" value={getPolitician(world,latest.winnerId)?.name}/></div>}</Card><Card title="Presidential archive"><div className="archive-cards">{world.elections.map((e)=><button key={e.id} onClick={()=>openPolitician(e.winnerId)}><span>YEAR {e.year}</span><strong>{getPolitician(world,e.winnerId)?.name}</strong><small>{e.winnerPartyName||party(getPolitician(world,e.winnerId)?.partyId).name} · {Math.max(e.unionEV,e.libertyEV)} electoral votes · {e.narrative}</small></button>)}</div></Card></>}
    {tab==='federal races'&&<><div className="metric-grid large"><Metric label="House districts" value="435" detail="individual incumbents"/><Metric label="Senate seats" value="100" detail="six-year classes"/><Metric label="Governorships" value="50" detail="state records"/><Metric label="Pending general races" value={pending?pending.house.length+pending.senate.length+pending.governor.length:0}/></div><Card title="Recent general elections"><ElectionResultTable world={world} records={world.raceArchive.slice(0,180)} openPolitician={openPolitician}/></Card></>}
    {tab==='primaries'&&<Card title="Recent party primaries" eyebrow={`${latestPrimaries.filter((r)=>r.uncontested).length} uncontested among these records`}><div className="table-wrap"><table><thead><tr><th>Year</th><th>Office</th><th>Party</th><th>Race</th><th>Winner</th><th>Field</th><th>Status</th></tr></thead><tbody>{latestPrimaries.map((r)=><tr key={r.id}><td>Y{r.year}</td><td>{r.office}</td><td><span style={{color:party(r.partyId).color}}>{r.partyName||party(r.partyId).name}</span></td><td>{r.districtId?getDistrict(world,r.districtId)?.name:getState(world,r.stateId)?.name}</td><td><button onClick={()=>openPolitician(r.winnerId)}>{getPolitician(world,r.winnerId)?.name}</button></td><td>{r.results.length}</td><td>{r.uncontested?'Unopposed':'Contested'}</td></tr>)}</tbody></table></div></Card>}
  </div>;
}
function cycleElectionTitle(world){ if(world.electionCycle.phase==='Governing'||world.electionCycle.phase==='Invisible Primary')return 'The next presidential contest'; if(world.electionCycle.phase==='Transition')return 'A president-elect prepares to govern'; return 'The presidential campaign'; }

function AbilityPanel({ politician }) { return <div className="attribute-grid">{ABILITY_KEYS.map(([key,label])=><div key={key}><span>{label}</span><Meter value={politician.abilities[key]} partyId={politician.partyId}/><b>{fmt(politician.abilities[key],0)}</b></div>)}</div>; }
function IdeologyPanel({ politician }) { return <div className="ideology-list">{IDEOLOGY_DIMENSIONS.map((d)=><div key={d.key}><div><small>{d.low}</small><strong>{d.label}</strong><small>{d.high}</small></div><Meter value={politician.ideology[d.key]} partyId={politician.partyId}/><b>{fmt(politician.ideology[d.key],0)}</b></div>)}</div>; }

function PoliticianProfile({ world, politician, openPolitician, openState }) {
  const [tab,setTab]=useState('overview');
  useEffect(()=>setTab('overview'),[politician.id]);
  const state=getState(world,politician.homeStateId);
  const officeState=getState(world,politician.officeStateId);
  const years=[...politician.annualHistory].sort((a,b)=>b.year-a.year);
  return <div className="profile">
    <div className="profile-hero" style={{'--party':party(politician.partyId).color}}><Avatar politician={politician} size="xxl"/><div><div className="profile-kicker"><Rarity rarity={politician.rarity}/><span>{party(politician.partyId).name}</span></div><h1>{politician.name}</h1><p>{politician.office}{officeState?` of ${officeState.name}`:''} · Age {politician.age} · {state.name}</p><div className="profile-tags"><span>{politician.background}</span><span>{party(politician.partyId).short}</span><span>{politician.status}</span></div></div><div className="profile-score"><span>Political power</span><strong>{fmt(politician.power,1)}</strong><small>Legacy {fmt(politician.legacy,1)}</small></div></div>
    <div className="tabs profile-tabs">{['overview','recognition','origin','year by year','career','elections','record & impact','ideology','relationships'].map((t)=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div>
    {tab==='overview'&&<div className="content-grid two-one"><div><Card title="Abilities" eyebrow="Campaigning and governing"><AbilityPanel politician={politician}/></Card><Card title="Recognition and popularity"><div className="metric-grid large"><Metric label="Home popularity" value={pct(politician.homePopularity)}/><Metric label="State recognition" value={pct(politician.stateRecognition)}/><Metric label="National popularity" value={pct(politician.nationalPopularity)}/><Metric label="National recognition" value={pct(politician.nationalRecognition)}/><Metric label="Elections won" value={politician.electionsWon}/><Metric label="Primaries" value={`${politician.primariesWon}-${politician.primariesLost}`}/></div></Card></div><div><Card title="Career snapshot"><dl className="facts"><div><dt>Current office</dt><dd>{politician.office}</dd></div><div><dt>In office since</dt><dd>Year {politician.officeSince}</dd></div><div><dt>Terms</dt><dd>House {politician.terms.house} · Senate {politician.terms.senate} · Governor {politician.terms.governor} · President {politician.terms.president}</dd></div><div><dt>Scandals</dt><dd>{politician.scandals}</dd></div><div><dt>Faction</dt><dd>{politician.factionId}</dd></div></dl></Card><Card title="Trajectory"><Sparkline values={[...politician.annualHistory].sort((a,b)=>a.year-b.year).map((y)=>y.power)}/><p className="caption">Political power by recorded year.</p></Card></div></div>}
    {tab==='recognition'&&<div className="content-grid two-one"><Card title="Fifty-state recognition" eyebrow="Recognition and favorability are independent"><div className="recognition-grid">{world.states.map((s,i)=>({state:s,recognition:getStateRecognition(politician,s.id,world),favorability:getStateFavorability(politician,s.id,world)})).sort((a,b)=>b.recognition-a.recognition).map(({state,recognition,favorability})=><button key={state.id} className="recognition-state" onClick={()=>openState(state.id)} style={{'--recognition':`${recognition}%`}}><span>{state.code}</span><strong>{fmt(recognition,0)}%</strong><small>{favorability>=50?'+':''}{fmt(favorability-50,0)} fav.</small></button>)}</div></Card><div><Card title="Recognition summary"><div className="metric-grid"><Metric label="Home state" value={pct(politician.stateRecognition)}/><Metric label="National weighted" value={pct(politician.nationalRecognition)}/><Metric label="Home favorability" value={`${politician.homePopularity>=50?'+':''}${fmt(politician.homePopularity-50,1)}`}/><Metric label="National favorability" value={`${politician.nationalPopularity>=50?'+':''}${fmt(politician.nationalPopularity-50,1)}`}/></div><p className="long-copy">A politician can be famous in one state and nearly anonymous elsewhere. Statewide races build local recognition; governors and senators spread regionally; presidential campaigns and nationally salient decisions spread recognition across the full country.</p></Card><Card title="Best-known states">{world.states.map((s,i)=>({state:s,r:getStateRecognition(politician,s.id,world),f:getStateFavorability(politician,s.id,world)})).sort((a,b)=>b.r-a.r).slice(0,10).map((x,index)=><button className="record-row" key={x.state.id} onClick={()=>openState(x.state.id)}><span>{index+1}</span><strong>{x.state.name}</strong><small>{fmt(x.r,1)}% know them</small><b>{x.f>=50?'+':''}{fmt(x.f-50,1)}</b></button>)}</Card></div></div>}
    {tab==='origin'&&<div className="content-grid two-one"><Card title="Before major politics" eyebrow={politician.background}><div className="timeline">{politician.prePoliticalCareer?.map((stage,index)=><div key={`${stage.role}-${index}`}><span>A{stage.startAge}<small>to {stage.endAge}</small></span><div><b>{stage.role}</b><p>Years {stage.startYear}–{stage.endYear}. This background helped define initial skills, voter-group affinities, and where recognition existed before the first major race.</p></div></div>)}</div></Card><Card title="Political entry"><dl className="facts"><div><dt>Career origin</dt><dd>{politician.background}</dd></div><div><dt>Home state</dt><dd>{state.name}</dd></div><div><dt>Entered major politics</dt><dd>Age {politician.career.find((e)=>e.type==='Entry') ? politician.career.find((e)=>e.type==='Entry').year-politician.birthYear : '—'}</dd></div><div><dt>Initial national route</dt><dd>{politician.careerOriginId==='celebrity'?'Broad recognition, weak institutional network':politician.careerOriginId==='military'?'Security prestige and wartime potential':politician.careerOriginId==='business'?'Fundraising and economic credibility':politician.careerOriginId==='academic'?'Policy credibility and educated constituencies':'Local/state network and home-state credibility'}</dd></div></dl></Card></div>}
    {tab==='year by year'&&<Card title="Year-by-year political record" eyebrow={`${years.length} archived annual snapshots`}><div className="table-wrap"><table><thead><tr><th>Year</th><th>Office</th><th>Approval</th><th>Home pop.</th><th>State rec.</th><th>National rec.</th><th>Power</th><th>Policies</th><th>Elections</th><th>State GDP rank</th></tr></thead><tbody>{years.map((y)=><tr key={y.year}><td>Y{y.year}</td><td>{y.office}</td><td>{y.approval==null?'—':pct(y.approval)}</td><td>{pct(y.homePopularity)}</td><td>{pct(y.stateRecognition)}</td><td>{pct(y.nationalRecognition)}</td><td>{fmt(y.power,1)}</td><td>{y.policies||0}</td><td>{y.elections||0}</td><td>{y.stateRank?`#${y.stateRank}`:'—'}</td></tr>)}</tbody></table></div></Card>}
    {tab==='career'&&<Card title="Complete career timeline" eyebrow={`${politician.career.length} permanent events`}><div className="timeline">{[...politician.career].sort((a,b)=>b.year-a.year||b.week-a.week).map((entry,index)=><div key={`${entry.year}-${entry.week}-${index}`}><span>Y{entry.year}<small>W{entry.week}</small></span><div><b>{entry.type}</b><p>{entry.event}</p></div></div>)}</div></Card>}
    {tab==='elections'&&<Card title="Election history" eyebrow={`${politician.electionsWon} wins · ${politician.electionsLost} losses`}><div className="table-wrap"><table><thead><tr><th>Year</th><th>Office</th><th>Stage</th><th>Result</th><th>Vote</th><th>Details</th></tr></thead><tbody>{[...politician.electionHistory].sort((a,b)=>b.year-a.year).map((e,index)=><tr key={`${e.year}-${index}`}><td>Y{e.year}</td><td>{e.office}</td><td>{e.stage}</td><td className={e.result==='Won'?'won':'lost'}>{e.result}</td><td>{e.voteShare==null?'—':pct(e.voteShare)}</td><td>{e.electoralVotes?`${e.electoralVotes} EV`:e.delegates?`${e.delegates} delegates`:e.fieldSize?`${e.fieldSize} candidates`:'—'}</td></tr>)}</tbody></table></div></Card>}
    {tab==='record & impact'&&<div className="content-grid two-one"><div><Card title="Governing record"><div className="record-grid">{Object.entries(politician.governingRecord).map(([key,value])=><div key={key}><span>{key.replace(/([A-Z])/g,' $1')}</span><strong>{value>=0?'+':''}{fmt(value,1)}</strong></div>)}</div></Card><Card title="Policy and decision archive" eyebrow="Each decision changes a jurisdiction and political coalition"><div className="policy-list">{politician.policyRecord.length?politician.policyRecord.map((record)=><article key={record.id}><div><span>Y{record.year} · {record.level}</span><strong>{record.name}</strong></div><p>{record.description}</p><small>{record.summary||'Political coalition effects recorded'}</small></article>):<p>No major executive decisions recorded yet.</p>}</div></Card></div><Card title="Coalition reputation" eyebrow="National standing created by ideology and decisions"><div className="coalition-list">{Object.entries(COALITION_LABELS).map(([key,label])=><div key={key}><span>{label}</span><Meter value={politician.coalition[key]} partyId={politician.partyId}/><b>{fmt(politician.coalition[key],0)}</b></div>)}</div><p className="long-copy">A state decision can create national effects. For example, signing an abortion restriction increases recognition and conservative standing while reducing progressive support; a protection law produces the opposite coalition movement.</p></Card></div>}
    {tab==='ideology'&&<div className="content-grid two-one"><Card title="Nine-dimensional ideology"><IdeologyPanel politician={politician}/></Card><Card title="Political identity"><p className="long-copy">This profile controls primary fit, voter-group reactions, policy choices, coalition growth, and the offices for which the politician is naturally competitive.</p><dl className="facts"><div><dt>Economic identity</dt><dd>{politician.ideology.economy<40?'State-directed':politician.ideology.economy>65?'Market liberal':'Mixed economy'}</dd></div><div><dt>Social identity</dt><dd>{politician.ideology.social<38?'Socially open':politician.ideology.social>65?'Traditionalist':'Moderate'}</dd></div><div><dt>Style</dt><dd>{politician.ideology.style>65?'Populist':politician.ideology.style<38?'Consensus-oriented':'Conventional partisan'}</dd></div></dl></Card></div>}
    {tab==='relationships'&&<div className="content-grid three"><Card title="Allies">{politician.relationships.allies.map((id)=><PoliticianButton key={id} world={world} id={id} onOpen={openPolitician}/>)}</Card><Card title="Rivals">{politician.relationships.rivals.map((id)=><PoliticianButton key={id} world={world} id={id} onOpen={openPolitician}/>)}</Card><Card title="Mentors and protégés">{[...politician.relationships.mentors,...politician.relationships.proteges].map((id)=><PoliticianButton key={id} world={world} id={id} onOpen={openPolitician}/>)}</Card></div>}
  </div>;
}

function PoliticiansPage({ world, selectedId, setSelectedId, openPolitician, openState }) {
  const [search,setSearch]=useState(''); const [rarity,setRarity]=useState('All'); const [office,setOffice]=useState('All'); const [stateId,setStateId]=useState('All');
  const selected=getPolitician(world,selectedId);
  if(selected)return <div className="page"><button className="back" onClick={()=>setSelectedId(null)}>← Politician directory</button><PoliticianProfile world={world} politician={selected} openPolitician={openPolitician} openState={openState}/></div>;
  const filtered=world.politicians.filter((p)=>p.status==='Active'&&(rarity==='All'||p.rarity===rarity)&&(office==='All'||p.office===office)&&(stateId==='All'||p.homeStateId===stateId)&&(!search||p.name.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.power-a.power);
  return <div className="page"><PageHeader eyebrow={`${world.politicians.filter((p)=>p.status==='Active').length.toLocaleString()} active political careers`} title="Politicians" description="Every officeholder, challenger, primary loser, rising star, governor, senator, representative, and presidential contender has a persistent career." /><div className="filters"><input placeholder="Search name" value={search} onChange={(e)=>setSearch(e.target.value)}/><select value={rarity} onChange={(e)=>setRarity(e.target.value)}><option>All</option>{Object.keys(RARITIES).map((r)=><option key={r}>{r}</option>)}</select><select value={office} onChange={(e)=>setOffice(e.target.value)}><option>All</option>{['President','Vice President','Governor','Senator','Representative','State Executive','State Legislator','Mayor','Private Citizen'].map((o)=><option key={o}>{o}</option>)}</select><select value={stateId} onChange={(e)=>setStateId(e.target.value)}><option value="All">All states</option>{world.states.map((s)=><option value={s.id} key={s.id}>{s.name}</option>)}</select></div><p className="result-count">{filtered.length.toLocaleString()} matches · displaying the top {Math.min(240,filtered.length)}</p><div className="directory-grid">{filtered.slice(0,240).map((p)=><button key={p.id} className="directory-person" onClick={()=>setSelectedId(p.id)}><Avatar politician={p}/><div><strong>{p.name}</strong><span>{p.office} · {getState(world,p.homeStateId)?.name}</span><small>Power {fmt(p.power,1)} · recognition {fmt(p.nationalRecognition,1)} / {fmt(p.stateRecognition,1)}</small></div><Rarity rarity={p.rarity}/></button>)}</div></div>;
}

function PartiesPage({ world, openPolitician }) {
  return <div className="page"><PageHeader eyebrow="Parties are historical institutions, not permanent labels" title="The Parties" description="Columbia always tends toward two dominant electoral coalitions, but the parties occupying those spaces can split, reorganize, change ideology, and disappear. Their full ancestry is preserved." /><div className="party-columns">{Object.values(world.parties).map((p)=><Card key={p.id} className="party-card" eyebrow={`${pct(p.nationalSupport)} national support · founded Y${p.foundedYear}`} title={p.name}><p>{p.description}</p><h3>National leader</h3><PoliticianButton world={world} id={p.leaderId} onOpen={openPolitician}/><h3>Current platform</h3><div className="ideology-list mini">{IDEOLOGY_DIMENSIONS.map((d)=><div key={d.key}><div><small>{d.low}</small><strong>{d.label}</strong><small>{d.high}</small></div><Meter value={p.platform?.[d.key]??50} partyId={p.id}/><b>{fmt(p.platform?.[d.key]??50,0)}</b></div>)}</div><h3>Party ancestry</h3><div className="party-lineage">{[...p.lineage].reverse().map((era,index)=><div key={era.id} className={era.dissolvedYear?'past':'current'}><span>{era.dissolvedYear?`Y${era.foundedYear}–${era.dissolvedYear}`:`Y${era.foundedYear}–present`}</span><strong>{era.name}</strong><small>{era.reason}</small>{index<p.lineage.length-1&&<em>← successor</em>}</div>)}</div><h3>Platform history</h3><div className="table-wrap compact-table"><table><thead><tr><th>Year</th><th>Economy</th><th>Social</th><th>Federal</th><th>Style</th><th>Support</th></tr></thead><tbody>{[...(p.platformHistory||[])].reverse().slice(0,12).map((h)=><tr key={h.year}><td>Y{h.year}</td><td>{fmt(h.platform.economy,0)}</td><td>{fmt(h.platform.social,0)}</td><td>{fmt(h.platform.federal,0)}</td><td>{fmt(h.platform.style,0)}</td><td>{pct(h.support)}</td></tr>)}</tbody></table></div><h3>Internal factions</h3><div className="faction-list">{p.factions.map((f)=><div key={f.id}><span>{f.name}</span><Meter value={f.influence} partyId={p.id}/><b>{pct(f.influence)}</b></div>)}</div></Card>)}</div></div>;
}

function CongressPage({ world, openPolitician, openState }) {
  const [stateId,setStateId]=useState(world.states[0].id);
  const state=getState(world,stateId);
  const delegation=state.districtIds.map((id)=>getDistrict(world,id)).map((d)=>({district:d,politician:getPolitician(world,d.incumbentId)}));
  const senators=world.senateSeats.filter((seat)=>seat.stateId===stateId).map((seat)=>({seat,politician:getPolitician(world,seat.incumbentId)}));
  return <div className="page"><PageHeader eyebrow="535 individual federal careers" title="Congress" description="The House is no longer abstracted. Every district has an incumbent, primary field, challenger history, and election record." /><div className="chamber-grid"><Card title="House of Representatives"><SplitBar union={world.government.house.union} liberty={world.government.house.liberty} total={435}/><p>All 435 seats face party primaries and general elections every two years.</p></Card><Card title="Senate"><SplitBar union={world.government.senate.union} liberty={world.government.senate.liberty} total={100}/><p>Each state has two individual senators serving staggered six-year terms.</p></Card></div><Card title="State delegation" eyebrow="Inspect every district and senator"><select value={stateId} onChange={(e)=>setStateId(e.target.value)}>{world.states.map((s)=><option key={s.id} value={s.id}>{s.name} · {s.houseSeats} House seats</option>)}</select><div className="delegation"><div><h3>Senators</h3>{senators.map(({seat,politician})=><button key={seat.id} onClick={()=>openPolitician(politician.id)}><Avatar politician={politician}/><span><strong>{politician.name}</strong><small>Seat {seat.seatNumber} · next election Y{seat.nextElectionYear}</small></span></button>)}</div><div><h3>House delegation</h3>{delegation.map(({district,politician})=><button key={district.id} onClick={()=>openPolitician(politician.id)}><span className="district-code">{district.name}</span><span><strong>{politician.name}</strong><small>{party(politician.partyId).short} · lean {district.lean<=0?'U':'L'}+{Math.abs(district.lean).toFixed(1)}</small></span></button>)}</div></div></Card></div>;
}

function StateProfile({ world, state, openPolitician }) {
  const governor=getPolitician(world,state.governorId);
  const senators=world.senateSeats.filter((seat)=>seat.stateId===state.id).map((seat)=>getPolitician(world,seat.incumbentId));
  const delegation=state.districtIds.map((id)=>getDistrict(world,id)).map((d)=>getPolitician(world,d.incumbentId));
  const recentYears=[...state.annualHistory].sort((a,b)=>b.year-a.year).slice(0,15);
  const metrics=[['GDP per capita','gdpPerCapita'],['Growth','growth'],['Unemployment','unemployment'],['Income','income'],['Budget','budget'],['Education','education'],['Health','health'],['Infrastructure','infrastructure'],['Crime','crime'],['Civil rights','rights'],['Environment','environment']];
  return <div><div className="state-hero"><div><span className="state-code big">{state.code}</span><div><h1>{state.name}</h1><p>{state.region} · {fmt(state.population,1)} million people · {state.electoralVotes} electoral votes</p></div></div><button onClick={()=>openPolitician(governor.id)}><Avatar politician={governor}/><span><small>Governor</small><strong>{governor.name}</strong><em>{party(governor.partyId).short} · approval {pct(governor.approval)}</em></span></button></div><div className="content-grid two-one"><div><Card title="State performance" eyebrow="Current value and national rank"><div className="state-metrics">{metrics.map(([label,key])=><div key={key}><span>{label}</span><strong>{key==='growth'||key==='unemployment'?`${fmt(state.metrics[key],1)}%`:fmt(state.metrics[key],1)}</strong><b>#{state.metricRanks[key]}</b></div>)}</div></Card><Card title="Performance history"><div className="table-wrap"><table><thead><tr><th>Year</th><th>Governor</th><th>GDP rank</th><th>Growth</th><th>Income rank</th><th>Budget</th><th>Rights</th></tr></thead><tbody>{recentYears.map((y)=><tr key={y.year}><td>Y{y.year}</td><td><button onClick={()=>openPolitician(y.governorId)}>{getPolitician(world,y.governorId)?.name}</button></td><td>#{y.ranks.gdpPerCapita}</td><td>{fmt(y.metrics.growth,1)}%</td><td>#{y.ranks.income}</td><td>{fmt(y.metrics.budget,1)}</td><td>{fmt(y.metrics.rights,1)}</td></tr>)}</tbody></table></div></Card><Card title="State decisions"><div className="policy-list">{state.policyHistory.slice(0,40).map((record)=><article key={record.id}><div><span>Y{record.year}</span><strong>{record.name}</strong></div><p>{record.description}</p><small>{record.summary}</small></article>)}</div></Card></div><div><Card title="Population coalitions" eyebrow="These groups affect primary and general-election calculations"><div className="population-groups">{[...state.groups].sort((a,b)=>b.share-a.share).map((g)=>{const labels=POPULATION_GROUP_ERA_LABELS[currentEra(world).id]||{};return <div key={g.groupId}><strong>{labels[g.groupId]||g.groupId.replace(/([A-Z])/g,' $1')}</strong><span>{pct(g.share)}</span><small>Turnout {fmt(g.enthusiasm,0)} · {party('union').short} loyalty {fmt(g.loyaltyUnion,0)}</small></div>})}</div></Card><Card title="Federal delegation"><h3>Senate</h3>{senators.map((p)=><PoliticianButton key={p.id} world={world} id={p.id} onOpen={openPolitician}/>) }<h3>House</h3><div className="mini-delegation">{delegation.map((p)=><PoliticianButton key={p.id} world={world} id={p.id} onOpen={openPolitician} compact/>)}</div></Card><Card title="Political ecosystem"><div className="metric-grid"><Metric label="Active politicians" value={state.politicianIds.map((id)=>getPolitician(world,id)).filter((p)=>p?.status==='Active').length}/><Metric label="House seats" value={state.houseSeats}/><Metric label="Primary system" value={state.primaryType}/><Metric label="Next governor race" value={`Y${state.nextGovernorElectionYear}`}/></div></Card></div></div></div>;
}

function StatesPage({ world, selectedId, setSelectedId, openPolitician }) {
  const selected=getState(world,selectedId);
  if(selected)return <div className="page"><button className="back" onClick={()=>setSelectedId(null)}>← Fifty states</button><StateProfile world={world} state={selected} openPolitician={openPolitician}/></div>;
  return <div className="page"><PageHeader eyebrow="Federalism, governors, and fifty political laboratories" title="The States" description="Every governor develops a measurable state record. Policies change economic, social, rights, and coalition outcomes before a career moves national." /><div className="state-directory">{world.states.map((s)=>{const g=getPolitician(world,s.governorId);return <button key={s.id} onClick={()=>setSelectedId(s.id)}><div><span className="state-code">{s.code}</span><strong>{s.name}</strong><small>{s.electoralVotes} EV · {s.houseSeats} districts</small></div><div><span>Governor</span><strong>{g.name}</strong><small>{party(g.partyId).short} · {pct(g.approval)}</small></div><div><span>GDP rank</span><strong>#{s.metricRanks.gdpPerCapita}</strong><small>Growth {fmt(s.metrics.growth,1)}%</small></div></button>})}</div></div>;
}

function GovernmentPage({ world, openPolitician }) {
  const president=getPolitician(world,world.government.presidentId);const vp=getPolitician(world,world.government.vicePresidentId);const s=world.country.society,n=world.country.nationalStats;
  return <div className="page"><PageHeader eyebrow={`${currentEra(world).name} · executive power and consequences`} title="Government" description="Presidential decisions alter institutions, social settlements, national statistics, international power, and the eventual historical reputation of the administration." /><div className="hero-grid"><Card title="President"><PoliticianButton world={world} id={president.id} onOpen={openPolitician}/><div className="metric-grid"><Metric label="Approval" value={pct(president.approval)}/><Metric label="Term" value={president.terms.president}/><Metric label="Major decisions" value={president.policyRecord.length}/><Metric label="Legacy" value={fmt(president.legacy,1)}/></div></Card><Card title="National model"><div className="metric-grid"><Metric label="Tax burden" value={`${fmt(s.taxBurden,1)}%`}/><Metric label="Social spending" value={fmt(s.socialSpending,1)}/><Metric label="Inequality" value={fmt(s.inequality,1)}/><Metric label="Quality of life" value={fmt(s.qualityLife,1)}/><Metric label="GDP / capita" value={fmt(n.gdpPerCapita,1)}/><Metric label="Military" value={fmt(n.military,1)}/></div></Card></div><Card title="Historical social settlement"><div className="metric-grid large"><Metric label="Slavery" value={s.slaveryLegal?`Legal · ${fmt(s.slaveryShare,1)}%`:'Abolished'}/><Metric label="Abolition support" value={pct(s.abolitionSupport)}/><Metric label="Indigenous relations" value={fmt(s.indigenousRelations,1)}/><Metric label="Integration" value={fmt(s.indigenousIntegration,1)}/><Metric label="Civil rights" value={fmt(s.civilRights,1)}/><Metric label="Industrialization" value={fmt(s.industrialization,1)}/></div></Card><Card title="Federal decisions & laws"><div className="policy-list columns">{world.government.laws.slice(0,100).map((law)=><article key={law.id}><div><span>Y{law.year} · {law.issue}</span><strong>{law.name}</strong></div><p>{law.description}</p><small>{law.summary}</small></article>)}</div></Card><Card title="Crises"><div className="crisis-list">{world.government.crises.map((c)=><div key={c.id}><span className={c.active?'live':''}>{c.active?'ACTIVE':'RESOLVED'}</span><strong>{c.name}</strong><p>{c.type} · severity {fmt(c.severity,1)} · began Y{c.startYear} W{c.startWeek}</p></div>)}</div></Card></div>;
}

function WorldPage({ world }) {
  const columbia={id:'columbia',name:world.country.shortName,population:world.country.population,gdp:world.country.nationalStats.gdp,gdpPerCapita:world.country.nationalStats.gdpPerCapita,qualityLife:world.country.society.qualityLife,literacy:world.country.society.literacy,lifeExpectancy:world.country.society.lifeExpectancy,military:world.country.nationalStats.military,technology:world.country.nationalStats.technology,inequality:world.country.society.inequality,taxBurden:world.country.society.taxBurden,rights:world.country.society.civilRights,majorPower:true};
  const countries=[columbia,...world.worldSystem.countries]; const ranked=(key,high=true)=>[...countries].sort((a,b)=>high?(b[key]??0)-(a[key]??0):(a[key]??0)-(b[key]??0));
  const rank=(key,high=true)=>ranked(key,high).findIndex((c)=>c.id==='columbia')+1;
  return <div className="page"><PageHeader eyebrow="A simplified world evolves alongside Columbia" title="World Comparison" description="Foreign countries are simulated at aggregate level so presidential choices can change Columbia’s place in the world without requiring thousands of foreign politicians." /><Card title="Columbia in the world" eyebrow={`Year ${world.date.year} · ${currentEra(world).name}`}><div className="metric-grid large"><Metric label="GDP" value={`#${rank('gdp')}`} detail={fmt(columbia.gdp,1)}/><Metric label="GDP / capita" value={`#${rank('gdpPerCapita')}`} detail={fmt(columbia.gdpPerCapita,1)}/><Metric label="Quality of life" value={`#${rank('qualityLife')}`} detail={fmt(columbia.qualityLife,1)}/><Metric label="Military" value={`#${rank('military')}`} detail={fmt(columbia.military,1)}/><Metric label="Technology" value={`#${rank('technology')}`} detail={fmt(columbia.technology,1)}/><Metric label="Low inequality" value={`#${rank('inequality',false)}`} detail={fmt(columbia.inequality,1)}/></div></Card><Card title="Columbia over time" eyebrow="National trend archive"><div className="trend-grid"><div><span>GDP per capita</span><Sparkline values={world.country.annualHistory.map((h)=>h.nationalStats.gdpPerCapita)}/><strong>{fmt(columbia.gdpPerCapita,1)}</strong></div><div><span>Quality of life</span><Sparkline values={world.country.annualHistory.map((h)=>h.society.qualityLife)}/><strong>{fmt(columbia.qualityLife,1)}</strong></div><div><span>Tax burden</span><Sparkline values={world.country.annualHistory.map((h)=>h.society.taxBurden)}/><strong>{fmt(columbia.taxBurden,1)}%</strong></div><div><span>Inequality</span><Sparkline values={world.country.annualHistory.map((h)=>h.society.inequality)}/><strong>{fmt(columbia.inequality,1)}</strong></div><div><span>Military strength</span><Sparkline values={world.country.annualHistory.map((h)=>h.nationalStats.military)}/><strong>{fmt(columbia.military,1)}</strong></div><div><span>Civil rights</span><Sparkline values={world.country.annualHistory.map((h)=>h.society.civilRights)}/><strong>{fmt(columbia.rights,1)}</strong></div></div><div className="table-wrap"><table><thead><tr><th>Year</th><th>President</th><th>GDP/cap</th><th>QoL</th><th>Taxes</th><th>Inequality</th><th>Military</th><th>World GDP rank</th></tr></thead><tbody>{[...world.country.annualHistory].reverse().slice(0,20).map((h)=><tr key={h.year}><td>Y{h.year}</td><td>{getPolitician(world,h.presidentId)?.name||'—'}</td><td>{fmt(h.nationalStats.gdpPerCapita,1)}</td><td>{fmt(h.society.qualityLife,1)}</td><td>{fmt(h.society.taxBurden,1)}%</td><td>{fmt(h.society.inequality,1)}</td><td>{fmt(h.nationalStats.military,1)}</td><td>{h.worldRanks?`#${h.worldRanks.gdp}`:'—'}</td></tr>)}</tbody></table></div></Card><Card title="International conflicts" eyebrow="Wars and major confrontations"><div className="archive-cards">{world.worldSystem.conflicts.length?world.worldSystem.conflicts.slice(0,24).map((c)=><div className="conflict-card" key={c.id}><span>Y{c.startYear}–{c.endYear}</span><strong>{c.name}</strong><small>{c.domestic?'Domestic conflict':c.opponentName?`Opponent: ${c.opponentName}`:c.type} · {c.outcome}</small></div>):<p>No major conflicts have entered the archive yet.</p>}</div></Card><Card title="International table"><div className="table-wrap"><table><thead><tr><th>Country</th><th>Pop. m</th><th>GDP</th><th>GDP/cap</th><th>QoL</th><th>Literacy</th><th>Life exp.</th><th>Military</th><th>Tech</th><th>Inequality</th><th>Taxes</th><th>Rights</th></tr></thead><tbody>{ranked('gdp').map((c)=><tr key={c.id} className={c.id==='columbia'?'highlight-row':''}><td><strong>{c.name}</strong></td><td>{fmt(c.population,1)}</td><td>{fmt(c.gdp,1)}</td><td>{fmt(c.gdpPerCapita,1)}</td><td>{fmt(c.qualityLife,1)}</td><td>{fmt(c.literacy,1)}</td><td>{fmt(c.lifeExpectancy,1)}</td><td>{fmt(c.military,1)}</td><td>{fmt(c.technology,1)}</td><td>{fmt(c.inequality,1)}</td><td>{fmt(c.taxBurden,1)}%</td><td>{fmt(c.rights,1)}</td></tr>)}</tbody></table></div></Card></div>;
}

function HistoryPage({ world, openPolitician }) {
  return <div className="page"><PageHeader eyebrow={`${currentEra(world).name} · the permanent national archive`} title="History" description="The archive records not only who won elections, but what kind of republic emerged: party systems, social settlements, wars, rights, economic development, and decisions that could have gone another way." /><div className="content-grid two-one"><Card title="Historical turning points" eyebrow={`${world.historical.pressureLog.length} major path-dependent decisions`}><div className="timeline">{world.historical.pressureLog.map((entry,index)=><div key={`${entry.year}-${index}`}><span>Y{entry.year}</span><div><b>Turning point</b><h3>{entry.title}</h3><p><strong>{getPolitician(world,entry.presidentId)?.name}:</strong> {entry.choice}</p><small>{entry.summary}</small></div></div>)}</div></Card><div><Card title="Current national path"><dl className="facts"><div><dt>Historical era</dt><dd>{currentEra(world).name}</dd></div><div><dt>Slavery</dt><dd>{world.country.society.slaveryLegal?'Legal':'Abolished'}</dd></div><div><dt>Indigenous integration</dt><dd>{fmt(world.country.society.indigenousIntegration,1)}</dd></div><div><dt>Industrialization</dt><dd>{fmt(world.country.society.industrialization,1)}</dd></div><div><dt>Civil rights</dt><dd>{fmt(world.country.society.civilRights,1)}</dd></div><div><dt>Party realignments</dt><dd>{world.historical.partyRealignments.length}</dd></div></dl></Card><Card title="Party family tree">{Object.values(world.parties).flatMap((p)=>p.lineage.map((l)=>({...l,slot:p.id}))).sort((a,b)=>b.foundedYear-a.foundedYear).map((l)=><div className="lineage-row" key={l.id}><span>Y{l.foundedYear}{l.dissolvedYear?`–${l.dissolvedYear}`:'–'}</span><strong>{l.name}</strong><small>{l.predecessorId?'Successor party':'Founding coalition'}</small></div>)}</Card></div></div><div className="history-layout"><Card title="National timeline"><div className="timeline">{world.history.map((entry,index)=><div key={`${entry.year}-${entry.week}-${index}`}><span>Y{entry.year}<small>W{entry.week}</small></span><div><b>{entry.type}</b><h3>{entry.title}</h3><p>{entry.text}</p></div></div>)}</div></Card><div><Card title="Administrations">{world.government.administrations.slice().reverse().map((a)=><button className="admin-row" key={a.id} onClick={()=>openPolitician(a.presidentId)}><strong>{getPolitician(world,a.presidentId)?.name}</strong><span>{a.partyName||party(a.partyId).short} · Y{a.startYear}–{a.endYear||'present'}</span><small>{a.laws.length} decisions · {a.crises.length} crises</small></button>)}</Card><Card title="Historical scale"><div className="metric-grid"><Metric label="Politicians generated" value={fmt(world.politicians.length)}/><Metric label="Archived races" value={fmt(world.raceArchive.length)}/><Metric label="Archived primaries" value={fmt(world.primaryArchive.length)}/><Metric label="State-year records" value={fmt(world.states.reduce((sum,s)=>sum+s.annualHistory.length,0))}/></div></Card></div></div></div>;
}

function RankingsPage({ world, openPolitician, openState }) {
  const topPower=[...world.politicians].sort((a,b)=>b.power-a.power).slice(0,15);
  const wins=[...world.politicians].sort((a,b)=>b.electionsWon-a.electionsWon).slice(0,15);
  const governors=world.states.map((s)=>getPolitician(world,s.governorId)).filter(Boolean).sort((a,b)=>b.governingRecord.stateRankChange-a.governingRecord.stateRankChange).slice(0,15);
  const young=world.records.youngestGovernor;
  return <div className="page"><PageHeader eyebrow="The political almanac" title="Rankings and Records" description="Track power, election victories, state transformations, young governors, presidential landslides, and the careers that survived defeat." /><div className="ranking-columns"><Card title="Most powerful figures"><RankList world={world} list={topPower} value={(p)=>fmt(p.power,1)} open={openPolitician}/></Card><Card title="Most election victories"><RankList world={world} list={wins} value={(p)=>p.electionsWon} open={openPolitician}/></Card><Card title="Best current governor records"><RankList world={world} list={governors} value={(p)=>`${p.governingRecord.stateRankChange>=0?'+':''}${fmt(p.governingRecord.stateRankChange,1)}`} open={openPolitician}/></Card></div><div className="content-grid two-one"><Card title="State transformations"><div className="archive-cards">{world.records.stateTransformations.map((r)=><button key={`${r.politicianId}-${r.year}`} onClick={()=>openPolitician(r.politicianId)}><span>Y{r.year} · {getState(world,r.stateId)?.name}</span><strong>{getPolitician(world,r.politicianId)?.name}</strong><small>Improved combined economic standing by {fmt(r.rankChange,1)} · GDP rank #{r.currentRank}</small></button>)}</div></Card><div><Card title="Youngest governor">{young?<button className="record-feature" onClick={()=>openPolitician(young.politicianId)}><Avatar politician={getPolitician(world,young.politicianId)} size="lg"/><strong>{getPolitician(world,young.politicianId)?.name}</strong><span>Age {young.age} · {getState(world,young.stateId)?.name} · Year {young.year}</span></button>:<p>No post-Year 1 governor record yet.</p>}</Card><Card title="Largest presidential wins">{world.records.landslides.slice(0,10).map((r,index)=><button className="record-row" key={`${r.year}-${r.winnerId}`} onClick={()=>openPolitician(r.winnerId)}><span>{index+1}</span><strong>{getPolitician(world,r.winnerId)?.name}</strong><small>Y{r.year}</small><b>{r.electoralVotes} EV</b></button>)}</Card></div></div></div>;
}
function RankList({world,list,value,open}){return <div className="ranking-list">{list.map((p,index)=><button key={p.id} onClick={()=>open(p.id)}><span>{index+1}</span><Avatar politician={p} size="xs"/><div><strong>{p.name}</strong><small>{p.office}</small></div><b>{value(p)}</b></button>)}</div>}

function SavesPage({ world, onWorldChange, toast }) {
  const [meta,setMeta]=useState({});const [seed,setSeed]=useState(world.seed);const slots=['slot-1','slot-2','slot-3'];
  const refresh=()=>getSaveMetadata(slots).then(setMeta).catch(()=>setMeta({}));
  useEffect(()=>{refresh();},[world.date.year,world.date.week]);
  const doSave=async(key)=>{await saveWorld(key,world);await refresh();toast(`Saved to ${key.replace('-',' ')}`)};
  const doLoad=async(key)=>{const loaded=await loadWorld(key);if(loaded?.schemaVersion===SCHEMA_VERSION){onWorldChange(loaded);toast(`Loaded ${key.replace('-',' ')}`)}else toast('That save uses an incompatible earlier universe model')};
  const doDelete=async(key)=>{await deleteWorld(key);await refresh();toast(`Deleted ${key.replace('-',' ')}`)};
  return <div className="page"><PageHeader eyebrow="IndexedDB saves for a huge universe" title="Saves and Universe" description="The expanded political database is stored in IndexedDB instead of localStorage, avoiding the old size ceiling created by thousands of careers and election records." /><div className="save-grid">{slots.map((key)=><Card key={key} title={key.replace('-',' ').toUpperCase()} eyebrow={meta[key]?new Date(meta[key].savedAt).toLocaleString():'Empty'}>{meta[key]?<div className="save-meta"><strong>Year {meta[key].year}, Week {meta[key].week}</strong><span>{meta[key].presidentName}</span><small>{meta[key].activePoliticians?.toLocaleString()} active politicians · seed {meta[key].seed}</small></div>:<p>No universe stored.</p>}<div className="button-row"><button onClick={()=>doSave(key)}>Save</button><button disabled={!meta[key]} onClick={()=>doLoad(key)}>Load</button><button disabled={!meta[key]} onClick={()=>doDelete(key)}>Delete</button></div></Card>)}</div><Card title="Create a new political universe"><div className="new-world"><input type="number" value={seed} onChange={(e)=>setSeed(Number(e.target.value)||1776)}/><button className="primary" onClick={()=>{onWorldChange(createWorld(seed));toast(`Created a new universe with seed ${seed}`)}}>Generate 6,200-politician republic</button></div></Card><Card title="Export or import JSON"><div className="button-row"><button onClick={()=>{const blob=new Blob([JSON.stringify(world)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`political-chronicle-y${world.date.year}-seed-${world.seed}.json`;a.click();URL.revokeObjectURL(url)}}>Export universe</button><label className="file-button">Import universe<input type="file" accept="application/json" onChange={(e)=>{const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(String(reader.result));if(imported.schemaVersion!==SCHEMA_VERSION)throw new Error('version');onWorldChange(imported);toast('Universe imported')}catch{toast('Import failed or incompatible version')}};reader.readAsText(file);e.target.value=''}}/></label></div></Card><Card title="Long simulation test"><div className="button-row"><button onClick={()=>onWorldChange(simulateYears(world,5))}>Simulate 5 years</button><button onClick={()=>onWorldChange(simulateYears(world,10))}>Simulate 10 years</button></div><p>These controls resolve all primaries, 435 House races per federal cycle, Senate classes, governorships, policies, state development, careers, retirements, and presidential contests.</p></Card></div>;
}

function AnnualReviewModal({ world, onContinue, onClose, openPolitician }) {
  const review=world.annualReview;if(!review)return null;const president=getPolitician(world,review.presidentId);const topStory=world.magazine.find((s)=>s.id===review.topStoryId);
  return <div className="modal-backdrop"><div className="annual-modal"><header><span>THE YEAR IN POLITICS</span><strong>YEAR {review.year}</strong><small>{world.country.name}</small></header><div className="annual-body"><div><span className="eyebrow">ANNUAL VERDICT</span><h2>{topStory?.title||`${president.name} closes the year`}</h2><p>{topStory?.text||'Another year of political history is complete.'}</p></div><div className="metric-grid large"><Metric label="Presidential approval" value={pct(review.presidentApproval)}/><Metric label="Growth" value={`${fmt(review.economy.growth,1)}%`}/><Metric label="Major events" value={review.majorEvents}/><Metric label="Active politicians" value={fmt(review.activePoliticians)}/></div><div className="annual-columns"><div><h3>Congress</h3><SplitBar union={review.house.union} liberty={review.house.liberty} total={435}/><SplitBar union={review.senate.union} liberty={review.senate.liberty} total={100}/></div><div><h3>Figures of the year</h3>{review.topPoliticianIds.map((id,index)=><button key={id} onClick={()=>{onClose();openPolitician(id)}}><span>{index+1}</span><strong>{getPolitician(world,id)?.name}</strong><small>{getPolitician(world,id)?.office}</small></button>)}</div></div></div><footer><button onClick={onClose}>Explore the archive</button><button className="primary" onClick={onContinue}>Move to Year {review.year+1} →</button></footer></div></div>;
}

function App() {
  const [world,setWorld]=useState(initialWorld);const [page,setPage]=useState('home');const [selectedPoliticianId,setSelectedPoliticianId]=useState(null);const [selectedStateId,setSelectedStateId]=useState(null);const [mobileNav,setMobileNav]=useState(false);const [busy,setBusy]=useState(false);const [toast,setToast]=useState(null);const [annualReviewHidden,setAnnualReviewHidden]=useState(false);const [autosaveLoaded,setAutosaveLoaded]=useState(false);
  window.__pcWorld=world;
  useEffect(()=>{loadWorld('autosave').then((saved)=>{if(saved?.schemaVersion===SCHEMA_VERSION)setWorld(saved)}).catch(()=>{}).finally(()=>setAutosaveLoaded(true));},[]);
  useEffect(()=>{if(!autosaveLoaded)return;const timer=setTimeout(()=>saveWorld('autosave',world).catch((error)=>console.warn('Autosave failed',error)),900);return()=>clearTimeout(timer)},[world,autosaveLoaded]);
  useEffect(()=>setAnnualReviewHidden(false),[world.annualReview?.year]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(null),2800);return()=>clearTimeout(t)},[toast]);
  const runUpdate=(updater,message)=>{setBusy(true);setTimeout(()=>{try{setWorld((current)=>updater(current));if(message)setToast(message)}finally{setBusy(false)}},20)};
  const navigate=(next)=>{setPage(next);setMobileNav(false);if(next!=='politicians')setSelectedPoliticianId(null);if(next!=='states')setSelectedStateId(null);window.scrollTo({top:0,behavior:'smooth'})};
  const openPolitician=(id)=>{setSelectedPoliticianId(id);setPage('politicians');setMobileNav(false);window.scrollTo({top:0,behavior:'smooth'})};
  const openState=(id)=>{setSelectedStateId(id);setPage('states');setMobileNav(false);window.scrollTo({top:0,behavior:'smooth'})};
  const content=useMemo(()=>{switch(page){case'magazine':return<MagazinePage world={world} openPolitician={openPolitician} openState={openState}/>;case'elections':return<ElectionsPage world={world} openPolitician={openPolitician} openState={openState}/>;case'politicians':return<PoliticiansPage world={world} selectedId={selectedPoliticianId} setSelectedId={setSelectedPoliticianId} openPolitician={openPolitician} openState={openState}/>;case'parties':return<PartiesPage world={world} openPolitician={openPolitician}/>;case'congress':return<CongressPage world={world} openPolitician={openPolitician} openState={openState}/>;case'states':return<StatesPage world={world} selectedId={selectedStateId} setSelectedId={setSelectedStateId} openPolitician={openPolitician}/>;case'government':return<GovernmentPage world={world} openPolitician={openPolitician}/>;case'world':return<WorldPage world={world}/>;case'history':return<HistoryPage world={world} openPolitician={openPolitician}/>;case'rankings':return<RankingsPage world={world} openPolitician={openPolitician} openState={openState}/>;case'saves':return<SavesPage world={world} onWorldChange={(w)=>{setWorld(w);setSelectedPoliticianId(null);setSelectedStateId(null)}} toast={setToast}/>;default:return<HomePage world={world} openPolitician={openPolitician} openState={openState} setPage={navigate}/>}},[page,world,selectedPoliticianId,selectedStateId]);
  return <div className="app-shell"><header className="topbar"><button className="brand" onClick={()=>navigate('home')}><span className="brand-mark">PC</span><span><strong>POLITICAL CHRONICLE</strong><small>{world.country.shortName} · Living History</small></span></button><div className="top-status"><span>Year {world.date.year}</span><strong>Week {world.date.week}</strong><em>{getCycleLabel(world)}</em></div><button className="mobile-menu" onClick={()=>setMobileNav(!mobileNav)}>☰</button></header><div className="app-body"><aside className={mobileNav?'open':''}><nav>{NAV_ITEMS.map(([id,label])=><button key={id} className={page===id?'active':''} onClick={()=>navigate(id)}><span>{label.slice(0,1)}</span>{label}</button>)}</nav><footer><span>Seed {world.seed}</span><small>v{APP_VERSION} · IndexedDB autosave</small></footer></aside><main><SimControls world={world} disabled={busy} onAdvance={(weeks)=>runUpdate((current)=>advanceWeeks(current,weeks,{stopOnMajor:weeks>1}),`Advanced ${weeks} week${weeks===1?'':'s'}`)} onNextEvent={()=>runUpdate(advanceToNextEvent,'Advanced to the next major event')} onEndYear={()=>runUpdate(advanceToEndOfYear,'Annual review ready')} onReview={()=>setAnnualReviewHidden(false)}/>{busy&&<div className="simulation-progress"><span/>Resolving thousands of political careers…</div>}{content}</main></div>{!annualReviewHidden&&<AnnualReviewModal world={world} onClose={()=>setAnnualReviewHidden(true)} onContinue={()=>runUpdate(moveToNextYear,`Year ${world.date.year+1} begins`)} openPolitician={openPolitician}/>} {toast&&<div className="toast">{toast}</div>}</div>;
}

export default App;
